questions.question:
With #include <map>, <print>, <stdexcept> and <string>, what does this print?

std::map<std::string, int> seats{{"CS101", 40}, {"CS102", 35}};
if (seats["CS103"] > 0) std::println("CS103 open");
if (seats.contains("CS104")) std::println("CS104 open");
if (seats.find("CS105") != seats.end()) std::println("CS105 open");
std::println("size {}", seats.size());
try {
    std::println("{}", seats.at("CS106"));
} catch (const std::out_of_range& e) {
    std::println("error: {}", e.what());
}
std::println("size {}", seats.size());
